from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route("/azimuth", methods=["POST"])
def azimuth():
    input = request.get_json()
    azimuth = input["azimuth"]
    direction = getDirection(azimuth)

    result = {
        "azimuth": azimuth,
        "direction": direction
    }

    return jsonify(result)

def getDirection(azimuth):
    if 0 <= azimuth < 90:
        return "Northeast"
    if 90 <= azimuth < 180:
        return "Southeast"
    if 180 <= azimuth < 270:
        return "Southwest"
    if 270 <= azimuth < 360:
        return "Northwest"
    else:
        return "Invalid input"

if __name__ == "__main__":
    app.run()
